110	/// Resolve the nearest config scope for a file target.
111	/// Returns `None` if the file belongs to the root scope.
112	pub(super) fn resolve_file_scope_config(
113	    file: &Path,
114	    root_config_dir: Option<&Path>,
115	    editorconfig_path: Option<&Path>,
116	    #[cfg(feature = "napi")] js_config_loader: Option<&JsConfigLoaderCb>,
117	) -> Result<Option<ConfigResolver>, String> {
118	    let Some(parent) = file.parent() else {
119	        return Ok(None);
120	    };
121	
122	    let mut resolver = ConfigResolver::from_config(
123	        parent,
124	        None,
125	        editorconfig_path,
126	        #[cfg(feature = "napi")]
127	        js_config_loader,
128	    )
129	    .map_err(|err| format!("Failed to load config for {}: {err}", file.display()))?;
130	
131	    // No config found, or same as root → belongs to root scope
132	    if resolver.config_dir().is_none() || resolver.config_dir() == root_config_dir {
133	        return Ok(None);
134	    }
135	
136	    resolver
137	        .build_and_validate()
138	        .map_err(|err| format!("Failed to parse config for {}: {err}", file.display()))?;
139	    Ok(Some(resolver))
140	}
